-- Core Tables
CREATE TABLE Station (id INT PK, name VARCHAR, city VARCHAR);
CREATE TABLE Train   (id INT PK, name VARCHAR, type ENUM('Express','Local'));
CREATE TABLE Schedule (
    id INT PK, train_id INT FK, departure_station INT FK,
    arrival_station INT FK, dept_time DATETIME, arr_time DATETIME
);
CREATE TABLE Seat (
    id INT PK, train_id INT FK, coach VARCHAR, seat_number INT,
    class ENUM('1A','2A','3A','SL'), status ENUM('AVAILABLE','BOOKED','LOCKED'),
    version INT DEFAULT 0   -- for optimistic locking
);
CREATE TABLE Booking (
    id INT PK, user_id INT FK, seat_id INT FK, schedule_id INT FK,
    pnr VARCHAR UNIQUE, status ENUM('CONFIRMED','CANCELLED'),
    idempotency_key VARCHAR UNIQUE,  -- prevent double booking
    created_at TIMESTAMP
);

-- Find routes between Delhi and Mumbai
SELECT s1.name src, s2.name dst, t.name train, sc.dept_time
FROM Schedule sc
JOIN Station s1 ON s1.id = sc.departure_station AND s1.city = 'Delhi'
JOIN Station s2 ON s2.id = sc.arrival_station   AND s2.city = 'Mumbai'
JOIN Train t ON t.id = sc.train_id;

